"use strict";

var _utilities = require("../../../utilities");
var _CoopsFilter = require("../CoopsFilter.utils");
describe('CoopsFilter.utils', function () {
  describe('convertCoopsToFilterOptions', function () {
    it('return empty', function () {
      expect((0, _CoopsFilter.convertCoopsToFilterOptions)(null)).toEqual([]);
    });
    it('should convert Coops To Filter Options ', function () {
      var coops = [{
        name: 'coop1'
      }];
      var options = [{
        id: 'coop1',
        label: 'coop1'
      }];
      expect((0, _CoopsFilter.convertCoopsToFilterOptions)(coops)).toEqual(options);
    });
  });
  describe('prependFilterName', function () {
    it('should prepend', function () {
      var callback = jest.fn();
      (0, _CoopsFilter.prependFilterName)(callback)('test');
      expect(callback.mock.calls[0][0]).toEqual(_utilities.FILTER_NAMES.coops);
      expect(callback.mock.calls[0][1]).toEqual('test');
    });
  });
});